using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;
public sealed class AIPressureTests:MonoBehaviour{
 public static bool UseAI;static bool booted;static HashSet<KeyCode> keys=new HashSet<KeyCode>();public static bool ReadKey(KeyCode k){return keys.Contains(k);}public static bool ReadDown(KeyCode k){return false;}
 public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=System.IO.Path.Combine(Application.dataPath,"..","ai-pressure-bindings.ini");var o=new GameObject("AIPressureTests");DontDestroyOnLoad(o);o.AddComponent<AIPressureTests>();}
 const BindingFlags SP=BindingFlags.Static|BindingFlags.NonPublic;Type pt;Component fan,zhao;Rigidbody2D fb,zb,ball;int checks,failures;float scale;
 void Check(bool ok,string text){checks++;if(!ok)failures++;Debug.Log((ok?"ABILITY PASS ":"ABILITY FAIL ")+text);}
 void Move(Component actor,Vector2 xy){var rb=(Rigidbody2D)pt.GetField("rb").GetValue(actor);actor.transform.position+=(Vector3)(xy-rb.position);foreach(var b in actor.GetComponentsInChildren<Rigidbody2D>()){b.velocity=Vector2.zero;b.angularVelocity=0;}Physics2D.SyncTransforms();}
 IEnumerator Scene(int mode){keys.Clear();UseAI=false;PlayerSkills.Enabled=mode==1;AbilityMode.Enabled=mode==2;AbilityMode.Reset();typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.4f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);fb=(Rigidbody2D)pt.GetField("rb").GetValue(fan);zb=(Rigidbody2D)pt.GetField("rb").GetValue(zhao);ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;Move(fan,new Vector2(-3*scale,fb.position.y));Move(zhao,new Vector2(3*scale,zb.position.y));ball.position=new Vector2(0,8);ball.gravityScale=0;yield return new WaitForSeconds(.4f);GameAIMod.OnBallReset();Collider2D fc=fan.transform.Find("Body").GetComponent<Collider2D>(),zc=zhao.transform.Find("Body").GetComponent<Collider2D>();float gap=fc.bounds.extents.x+zc.bounds.extents.x-.02f*scale;Move(fan,new Vector2(-gap*.5f,fb.position.y));Move(zhao,new Vector2(gap*.5f,fb.position.y));float y=fan.transform.Find("L_LowLeg").GetComponent<Collider2D>().bounds.min.y+ball.GetComponent<Collider2D>().bounds.extents.y+.02f;ball.position=new Vector2(0,y);ball.gravityScale=1;ball.velocity=Vector2.zero;Physics2D.SyncTransforms();keys.Add(ControlBindings.Get(true,GameControlAction.Right));keys.Add(ControlBindings.Get(false,GameControlAction.Left));yield return new WaitForFixedUpdate();}
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=120;QualitySettings.vSyncCount=0;AudioListener.volume=0;yield return new WaitForSeconds(.2f);for(int mode=0;mode<3;mode++){yield return Scene(mode);bool fanFull=false,zhaoFull=false,fanParity=false,zhaoParity=false;for(int i=0;i<15;i++){UseAI=true;float ax=GameAIMod.GetAxis("Horizontal",fan),zx=GameAIMod.GetAxis("Horizontal2",zhao);object fs=typeof(GameAIMod).GetMethod("GetState",SP).Invoke(null,new object[]{fan}),zs=typeof(GameAIMod).GetMethod("GetState",SP).Invoke(null,new object[]{zhao});bool ft=(bool)fs.GetType().GetField("contesting").GetValue(fs),zt=(bool)zs.GetType().GetField("contesting").GetValue(zs);float ff=PlayerMovement.GetMovementForce(100,fan),zf=PlayerMovement.GetMovementForce(100,zhao);UseAI=false;float hf=PlayerMovement.GetMovementForce(100,fan),hz=PlayerMovement.GetMovementForce(100,zhao);if(ft&&ax>.99f){fanFull=true;fanParity|=Mathf.Abs(ff-hf)<.01f;}if(zt&&zx<-.99f){zhaoFull=true;zhaoParity|=Mathf.Abs(zf-hz)<.01f;}UseAI=true;yield return new WaitForFixedUpdate();}Check(fanFull&&fanParity,"Fan AI equals held D native push mode="+mode);Check(zhaoFull&&zhaoParity,"Zhao AI equals held left native push mode="+mode);keys.Clear();UseAI=false;}Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);}
}